package com.bitap.keyboard.core

import java.io.File
import java.security.MessageDigest
import java.time.LocalDateTime
import java.time.format.DateTimeFormatter
import java.util.Locale
import kotlin.math.sqrt
import org.junit.Assert.assertTrue
import org.junit.Assume.assumeTrue
import org.junit.Test

/**
 * Pinyin evaluation v2 (D01).
 *
 * Reads the independent v2 corpus generated by eval/v2/corpus/build_v2_corpus.py.
 * The dev split runs by default and writes build/pinyin-v2-eval-dev.txt.
 * The validation split runs only when PINYIN_V2_VALIDATION=1 and writes an
 * aggregate-only report (no case ids, inputs or expected strings).
 *
 * Metrics: Top1, Top5, full coverage, correct-path oracle, rankCost and
 * per-category error rates. Interaction cases (mixed Chinese/English and
 * Arabic-digit items) are excluded from the engine-accuracy denominator and
 * reported separately as prefix hits.
 */
class PinyinV2EvalTest {

    private data class EvalCase(
        val id: String,
        val category: String,
        val input: String,
        val expected: List<String>,
        val note: String,
        val source: String,
    )

    private data class CaseResult(
        val case: EvalCase,
        val rank: Int,
        val topCandidates: List<String>,
        val latencyNanos: Long,
        val scored: Boolean,
        val fullCoverage: Boolean,
        val oracleHit: Boolean,
        val failureReason: String?,
    ) {
        val top1: Boolean get() = rank == 0
        val top5: Boolean get() = rank in 0..4
        val rankCost: Int get() = if (rank >= 0) rank + 1 else MISS_RANK_COST
    }

    private val categoryOrder = listOf(
        "natural_short",
        "natural_medium",
        "natural_long",
        "homophone",
        "shorthand",
        "typo",
        "mixed_pinyin",
        "number_punct",
        "proper_noun",
        "mixed_en",
    )

    private val categoryLabels = mapOf(
        "natural_short" to "自然短句",
        "natural_medium" to "自然中句",
        "natural_long" to "自然长句",
        "homophone" to "同音词歧义",
        "shorthand" to "简拼",
        "typo" to "错拼",
        "mixed_pinyin" to "混拼",
        "number_punct" to "数字与标点",
        "proper_noun" to "专有名词",
        "mixed_en" to "中英混输（交互）",
    )

    @Test
    fun evaluateV2DevCorpus() {
        val root = findRepoRoot()
        val dictionaryFile = File(root, "app/src/main/assets/pinyin_dict.tsv")
        val corpusFile = File(root, "eval/v2/corpus/pinyin_cases_v2_dev.tsv")
        assumeTrue("v2 dev corpus not found: " + corpusFile.absolutePath, corpusFile.isFile)
        assumeTrue("dictionary not found: " + dictionaryFile.absolutePath, dictionaryFile.isFile)
        val cases = loadCases(corpusFile)
        assertTrue("v2 dev corpus needs >=1000 cases but was " + cases.size, cases.size >= 1000)
        validateCorpusShape(cases, requireSplit = "dev")

        val dictionaryWords = loadDictionaryWords(dictionaryFile)
        val engine = dictionaryFile.useLines { lines -> PinyinEngine.fromLines(lines) }
        assertTrue("engine failed to load dictionary", engine.isReady)

        // Warm up JIT on a fixed subset.
        cases.take(24).forEach { engine.search(it.input, limit = SEARCH_LIMIT) }

        val results = cases.map { runCase(engine, it, dictionaryWords) }
        val report = buildReport("dev", root, corpusFile, engine, results, includeDetails = true)
        val outputFile = File(root, "build/pinyin-v2-eval-dev.txt")
        outputFile.parentFile?.mkdirs()
        outputFile.writeText(report, Charsets.UTF_8)
        println(report)
        println("wrote " + outputFile.absolutePath)
    }

    @Test
    fun evaluateV2ValidationCorpus() {
        assumeTrue(
            "v2 validation runs only when PINYIN_V2_VALIDATION=1 (acceptance only)",
            System.getenv("PINYIN_V2_VALIDATION") == "1",
        )
        val root = findRepoRoot()
        val dictionaryFile = File(root, "app/src/main/assets/pinyin_dict.tsv")
        val corpusFile = File(root, "eval/v2/corpus/pinyin_cases_v2_validation.tsv")
        assumeTrue("v2 validation corpus not found: " + corpusFile.absolutePath, corpusFile.isFile)
        assumeTrue("dictionary not found: " + dictionaryFile.absolutePath, dictionaryFile.isFile)
        val cases = loadCases(corpusFile)
        assertTrue("v2 validation corpus needs >=500 cases but was " + cases.size, cases.size >= 500)
        validateCorpusShape(cases, requireSplit = "validation")

        val dictionaryWords = loadDictionaryWords(dictionaryFile)
        val engine = dictionaryFile.useLines { lines -> PinyinEngine.fromLines(lines) }
        assertTrue("engine failed to load dictionary", engine.isReady)
        cases.take(24).forEach { engine.search(it.input, limit = SEARCH_LIMIT) }

        // Validation is acceptance-only: aggregate output, never per-case detail.
        val results = cases.map { runCase(engine, it, dictionaryWords) }
        val report = buildReport("validation", root, corpusFile, engine, results, includeDetails = false)
        val outputFile = File(root, "build/pinyin-v2-eval-validation.txt")
        outputFile.parentFile?.mkdirs()
        outputFile.writeText(report, Charsets.UTF_8)
        println(report)
        println("wrote " + outputFile.absolutePath)
    }

    private fun validateCorpusShape(cases: List<EvalCase>, requireSplit: String) {
        val ids = cases.map { it.id }.toSet()
        assertTrue("duplicate case ids", ids.size == cases.size)
        val inputs = cases.map { it.input }.toSet()
        assertTrue("duplicate inputs", inputs.size == cases.size)
        categoryOrder.forEach { category ->
            assertTrue("corpus misses category " + category, cases.any { it.category == category })
        }
        cases.forEach { case ->
            assertTrue("case " + case.id + " misses expected answers", case.expected.isNotEmpty())
            assertTrue("case " + case.id + " has empty input", case.input.isNotEmpty())
            assertTrue("case " + case.id + " has empty note", case.note.isNotEmpty())
            assertTrue("case " + case.id + " has wrong split prefix", case.id.startsWith(if (requireSplit == "dev") "v2d-" else "v2v-"))
        }
    }

    private fun runCase(engine: PinyinEngine, case: EvalCase, dictionaryWords: Set<String>): CaseResult {
        val started = System.nanoTime()
        val candidates = engine.search(case.input, limit = SEARCH_LIMIT)
        val elapsed = System.nanoTime() - started
        val scored = !isInteraction(case)
        var bestRank = -1
        candidates.forEachIndexed { index, candidate ->
            if (bestRank < 0 && matches(candidate, case)) bestRank = index
        }
        var fullCoverage = false
        var oracleHit = false
        if (scored) {
            val fullPool = engine.search(case.input, limit = FULL_LIMIT)
            fullCoverage = fullPool.any { it.consumedInputLength >= requiredCoverage(case.input) }
            oracleHit = fullPool.any { matches(it, case) }
        }
        val failureReason = if (bestRank in 0..4) null else {
            classifyFailure(case, bestRank, candidates.map { it.word }, dictionaryWords)
        }
        return CaseResult(
            case = case,
            rank = bestRank,
            topCandidates = candidates.map { it.word },
            latencyNanos = elapsed,
            scored = scored,
            fullCoverage = fullCoverage,
            oracleHit = oracleHit,
            failureReason = failureReason,
        )
    }

    private fun isInteraction(case: EvalCase): Boolean =
        case.category == "mixed_en" || (case.category == "number_punct" && case.input.any { it.isDigit() })

    /**
     * Candidate matching. Whole-sentence categories must cover every typed
     * character. Interaction categories only require the Chinese prefix:
     * mixed_en commits the English tail raw and digit items commit the digit raw.
     */
    private fun matches(candidate: Candidate, case: EvalCase): Boolean {
        if (isInteraction(case)) {
            val prefix = buildString {
                for (char in case.expected.first()) {
                    if (!isCjk(char)) break
                    append(char)
                }
            }
            return prefix.length >= 2 && normalizeForMatch(candidate.word) == normalizeForMatch(prefix)
        }
        val candidateText = normalizeForMatch(candidate.word)
        if (candidateText.isEmpty()) return false
        val coverage = requiredCoverage(case.input)
        return case.expected.any { alternative ->
            val expectedText = normalizeForMatch(alternative)
            expectedText.isNotEmpty() && candidateText == expectedText && candidate.consumedInputLength >= coverage
        }
    }

    private fun requiredCoverage(input: String): Int =
        input.count { it.isLetterOrDigit() || it == '\'' }

    private fun classifyFailure(
        case: EvalCase,
        bestRank: Int,
        topCandidates: List<String>,
        dictionaryWords: Set<String>,
    ): String {
        if (isInteraction(case)) return "交互"
        if (case.category in setOf("typo", "shorthand", "mixed_pinyin")) return "容错"
        if (bestRank >= 5) return "排序"
        if (topCandidates.isEmpty()) return "切分"
        val alternatives = case.expected.map { normalizeForMatch(it) }.filter { it.isNotEmpty() }
        if (alternatives.any { dictionaryWords.contains(it) }) return "排序"
        val target = alternatives.firstOrNull() ?: return "排序"
        if (!isComposable(target, dictionaryWords)) return "缺词"
        val sameSkeleton = topCandidates.any { candidate ->
            candidate.length == target.length && commonPrefixLength(target, candidate) >= 2
        }
        if (sameSkeleton) return "排序"
        val maxOverlap = topCandidates.maxOfOrNull { candidateOverlap(target, it) } ?: 0.0
        if (maxOverlap >= 0.5) return "切分"
        return "排序"
    }

    private fun buildReport(
        split: String,
        root: File,
        corpusFile: File,
        engine: PinyinEngine,
        results: List<CaseResult>,
        includeDetails: Boolean,
    ): String {
        val scored = results.filter { it.scored }
        val interaction = results.filter { !it.scored }
        val builder = StringBuilder()
        builder.appendLine("# Bitap pinyin evaluation v2 (aggregate)")
        builder.appendLine("split=" + split)
        builder.appendLine("generatedAt=" + LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME))
        builder.appendLine("hostOs=" + System.getProperty("os.name") + " " + System.getProperty("os.version"))
        builder.appendLine("jvm=" + System.getProperty("java.vm.name") + " " + System.getProperty("java.version"))
        builder.appendLine("corpus=" + corpusFile.relativeTo(root).path.replace('\\', '/'))
        builder.appendLine("corpusSha256=" + sha256(corpusFile))
        builder.appendLine("dictionaryEntries=" + engine.entryCount)
        builder.appendLine("searchLimit=" + SEARCH_LIMIT + " oracleLimit=" + FULL_LIMIT)
        builder.appendLine("cases=" + results.size + " engineScored=" + scored.size + " interactionExcluded=" + interaction.size)
        builder.appendLine()
        appendOverall(builder, "allCases", results)
        appendOverall(builder, "engineScored", scored)
        appendEngineExtras(builder, scored)
        builder.appendLine()
        appendByCategory(builder, results)
        builder.appendLine()
        appendInteraction(builder, interaction)
        builder.appendLine()
        appendLatency(builder, results)
        builder.appendLine("failureReasons=" + failureReasons(results))
        if (includeDetails) {
            builder.appendLine()
            builder.appendLine("[caseDetail]")
            results.forEach { result ->
                builder.appendLine(
                    result.case.id +
                        " category=" + result.case.category +
                        " rank=" + result.rank +
                        " top1=" + result.top1 +
                        " top5=" + result.top5 +
                        " scored=" + result.scored +
                        " fullCoverage=" + result.fullCoverage +
                        " oracle=" + result.oracleHit +
                        " cost=" + result.rankCost +
                        " reason=" + (result.failureReason ?: "-") +
                        " input=" + result.case.input +
                        " expected=" + result.case.expected.joinToString("|") +
                        " got=" + result.topCandidates.take(5).joinToString("|"),
                )
            }
        }
        return builder.toString()
    }

    private fun appendOverall(builder: StringBuilder, label: String, results: List<CaseResult>) {
        builder.appendLine("[" + label + "]")
        builder.appendLine("n=" + results.size)
        builder.appendLine("top1=" + ratio(results.count { it.top1 }, results.size) + " ci95=" + wilson(results.count { it.top1 }, results.size))
        builder.appendLine("top5=" + ratio(results.count { it.top5 }, results.size) + " ci95=" + wilson(results.count { it.top5 }, results.size))
        builder.appendLine("rankCost.avg=" + averageCost(results) + " total=" + results.sumOf { it.rankCost })
    }

    private fun appendEngineExtras(builder: StringBuilder, scored: List<CaseResult>) {
        builder.appendLine("fullCoverage=" + ratio(scored.count { it.fullCoverage }, scored.size))
        builder.appendLine("oracleHit=" + ratio(scored.count { it.oracleHit }, scored.size))
        builder.appendLine("top5ErrorRate=" + percent(scored.count { !it.top5 }, scored.size) + "%")
    }

    private fun appendByCategory(builder: StringBuilder, results: List<CaseResult>) {
        builder.appendLine("[byCategory]")
        categoryOrder.forEach { category ->
            val all = results.filter { it.case.category == category }
            if (all.isEmpty()) return@forEach
            val scored = all.filter { it.scored }
            val line = StringBuilder()
            line.append("  ").append(category).append(" (").append(categoryLabels[category] ?: category).append("): ")
            line.append("n=").append(all.size)
            if (scored.isEmpty()) {
                line.append(" interaction=all")
                line.append(" prefixTop1=").append(ratio(all.count { it.top1 }, all.size))
                line.append(" prefixTop5=").append(ratio(all.count { it.top5 }, all.size))
            } else {
                line.append(" scored=").append(scored.size)
                line.append(" top1=").append(ratio(scored.count { it.top1 }, scored.size))
                line.append(" top5=").append(ratio(scored.count { it.top5 }, scored.size))
                line.append(" rankCost=").append(averageCost(scored))
                line.append(" fullCoverage=").append(ratio(scored.count { it.fullCoverage }, scored.size))
                line.append(" oracle=").append(ratio(scored.count { it.oracleHit }, scored.size))
                line.append(" top1Ci95=").append(wilson(scored.count { it.top1 }, scored.size))
            }
            if (all.size != scored.size && scored.isNotEmpty()) {
                line.append(" interaction=").append(all.size - scored.size)
                line.append(" prefixTop1=").append(ratio(all.count { !it.scored && it.top1 }, all.size - scored.size))
            }
            builder.appendLine(line.toString())
        }
    }

    private fun appendInteraction(builder: StringBuilder, interaction: List<CaseResult>) {
        builder.appendLine("[interaction]")
        val mixed = interaction.filter { it.case.category == "mixed_en" }
        val digits = interaction.filter { it.case.category == "number_punct" }
        builder.appendLine("mixed_en.n=" + mixed.size + " prefixTop1=" + ratio(mixed.count { it.top1 }, mixed.size) + " prefixTop5=" + ratio(mixed.count { it.top5 }, mixed.size))
        builder.appendLine("number_punct_digit.n=" + digits.size + " prefixTop1=" + ratio(digits.count { it.top1 }, digits.size) + " prefixTop5=" + ratio(digits.count { it.top5 }, digits.size))
    }

    private fun appendLatency(builder: StringBuilder, results: List<CaseResult>) {
        val values = results.map { it.latencyNanos }.sorted()
        if (values.isEmpty()) {
            builder.appendLine("[latency] n/a")
            return
        }
        fun percentile(percent: Int): Double {
            val index = ((values.size - 1) * percent / 100).coerceIn(0, values.lastIndex)
            return values[index] / 1_000_000.0
        }
        builder.appendLine(
            "[latency] p50=" + formatMillis(percentile(50)) +
                " p95=" + formatMillis(percentile(95)) +
                " p99=" + formatMillis(percentile(99)) +
                " max=" + formatMillis(values.last() / 1_000_000.0),
        )
    }

    private fun failureReasons(results: List<CaseResult>): String {
        val reasons = LinkedHashMap<String, Int>()
        results.filter { !it.top5 }.forEach { result ->
            val reason = result.failureReason ?: "排序"
            reasons[reason] = (reasons[reason] ?: 0) + 1
        }
        return if (reasons.isEmpty()) "none" else reasons.entries.joinToString(" ") { it.key + "=" + it.value }
    }

    private fun loadCases(file: File): List<EvalCase> = file.useLines { lines ->
        lines.mapNotNull { raw ->
            val line = raw.removePrefix("\uFEFF").trimEnd('\r')
            if (line.isBlank() || line.trimStart().startsWith("#")) return@mapNotNull null
            val parts = line.split('\t')
            require(parts.size == 6) { "malformed v2 corpus line: " + line }
            EvalCase(
                id = parts[0].trim(),
                category = parts[1].trim(),
                input = parts[2].trim(),
                expected = parts[3].split('|').map { it.trim() }.filter { it.isNotEmpty() },
                note = parts[4].trim(),
                source = parts[5].trim(),
            )
        }.toList()
    }

    private fun loadDictionaryWords(file: File): Set<String> {
        val words = HashSet<String>()
        file.forEachLine(Charsets.UTF_8) { raw ->
            val line = raw.removePrefix("\uFEFF").trimEnd('\r')
            if (line.isBlank() || line.trimStart().startsWith("#")) return@forEachLine
            val parts = line.split('\t')
            if (parts.size < 2) return@forEachLine
            val word = parts[1].trim()
            if (word.isNotEmpty()) words.add(word)
        }
        return words
    }

    private fun sha256(file: File): String {
        val digest = MessageDigest.getInstance("SHA-256")
        file.inputStream().use { stream ->
            val buffer = ByteArray(1 shl 16)
            while (true) {
                val read = stream.read(buffer)
                if (read < 0) break
                digest.update(buffer, 0, read)
            }
        }
        return digest.digest().joinToString("") { String.format(Locale.ROOT, "%02x", it) }
    }

    private fun findRepoRoot(): File {
        var directory: File? = File(System.getProperty("user.dir") ?: ".").absoluteFile
        while (directory != null) {
            if (File(directory, "eval/v2/corpus/pinyin_cases_v2_dev.tsv").isFile &&
                File(directory, "app/src/main/assets/pinyin_dict.tsv").isFile
            ) {
                return directory
            }
            directory = directory.parentFile
        }
        error("repository root not found from " + System.getProperty("user.dir"))
    }

    private fun isComposable(text: String, words: Set<String>): Boolean {
        var position = 0
        while (position < text.length) {
            var matched = 0
            val maxLength = minOf(10, text.length - position)
            for (length in maxLength downTo 1) {
                if (words.contains(text.substring(position, position + length))) {
                    matched = length
                    break
                }
            }
            if (matched == 0) return false
            position += matched
        }
        return true
    }

    private fun commonPrefixLength(left: String, right: String): Int {
        var index = 0
        while (index < left.length && index < right.length && left[index] == right[index]) index++
        return index
    }

    private fun candidateOverlap(expected: String, candidate: String): Double {
        if (expected.isEmpty() || candidate.isEmpty()) return 0.0
        val remaining = HashMap<Char, Int>()
        expected.forEach { remaining[it] = (remaining[it] ?: 0) + 1 }
        var common = 0
        candidate.forEach { char ->
            val count = remaining[char] ?: 0
            if (count > 0) {
                common++
                remaining[char] = count - 1
            }
        }
        return common.toDouble() / expected.length
    }

    private fun normalizeForMatch(text: String): String =
        text.filter { it.isLetterOrDigit() || isCjk(it) }

    private fun isCjk(char: Char): Boolean =
        char.code in 0x3400..0x4DBF || char.code in 0x4E00..0x9FFF || char.code in 0xF900..0xFAFF

    private fun averageCost(results: List<CaseResult>): String =
        if (results.isEmpty()) "0.00" else String.format(Locale.ROOT, "%.2f", results.sumOf { it.rankCost }.toDouble() / results.size)

    private fun ratio(value: Int, total: Int): String =
        value.toString() + "/" + total + "(" + percent(value, total) + "%)"

    private fun percent(value: Int, total: Int): String =
        if (total == 0) "0.0" else String.format(Locale.ROOT, "%.1f", value * 100.0 / total)

    private fun wilson(hit: Int, total: Int): String {
        if (total == 0) return "n/a"
        val p = hit.toDouble() / total
        val z = 1.96
        val z2 = z * z
        val denominator = 1.0 + z2 / total
        val center = (p + z2 / (2.0 * total)) / denominator
        val half = z * sqrt(p * (1.0 - p) / total + z2 / (4.0 * total * total)) / denominator
        val low = ((center - half) * 100.0).coerceIn(0.0, 100.0)
        val high = ((center + half) * 100.0).coerceIn(0.0, 100.0)
        return String.format(Locale.ROOT, "%.1f%% [%.1f%%, %.1f%%]", p * 100.0, low, high)
    }

    private fun formatMillis(value: Double): String = String.format(Locale.ROOT, "%.3f", value)

    companion object {
        private const val SEARCH_LIMIT = 8
        private const val FULL_LIMIT = 64
        private const val MISS_RANK_COST = 9
    }
}
